section.code:
const when = event.when as dateTime;

"2026-10-11" as date;
// Type assertion failed: expected date but got string;
//     write "2026-10-11"date or to_date(v)

5 as double;
// Type assertion failed: expected double but got integer;
//     write to_double(v)

function days(n: integer) { return n; }
days(1.9);    // Type error in parameter: expected integer but got double;
              //     write to_integer(v)

const d: dateTime = "abc";   // write "abc"dateTime or to_dateTime(v)

"a" + 1;      // Parameter 2 of function 'add<string>' must evaluate to
              //     data type 'string' ...; write to_string(v)

#compile strictDouble;
const ratio = function(a: double, b: double): double { return a / b; };
ratio(1.0, 0.0);   /* error: IEEE 754 division by zero */
